    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("draft",alarm.json().toString());out.putString("originalAlarm",originalAlarm.json().toString());out.putBoolean("originalExisted",originalExisted);out.putString("route",route);out.putString("inspectedTask",inspectedTask);out.putInt("taskRounds",taskRounds);out.putInt("taskIndex",taskIndex);out.putInt("taskSteps",taskSteps);out.putInt("taskJournal",taskJournal);out.putString("qrRequest",qrRequest);out.putString("pictureRequest",pictureRequest);out.putString("solarRequest",solarRequest);out.putString("goalRequest",goalRequest);out.putString("goalNotice",goalNotice);out.putString("walkPermissionError",walkPermissionError);out.putString("mathError",mathError);out.putString("saveError",saveError);try{out.putString("taskMath",MathSettingsJson.encode(taskMath).toString());}catch(JSONException impossible){throw new IllegalStateException(impossible);}out.putString("routineDraft",ChallengeRoutineJson.encode(routineDraft).toString());out.putInt("soundTab",soundTab);if(dateCalendar!=null&&dateCalendar.showing())out.putBundle("alarmDateCalendar",dateCalendar.state());if(toneScreen!=null)out.putBundle("toneState",toneScreen.save());else if(toneState!=null)out.putBundle("toneState",toneState);if(settingsDialog instanceof SleepPicker.StateDialog)out.putBundle("picker",settingsDialog.onSaveInstanceState());}
    private void back(){if(!route.equals("edit")){route=(route.equals("gentle")||route.equals("soundmodes"))?"sound":route.equals("task")?"challenge":"edit";render();}else finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    private void go(String next){if(next.equals("challenge")&&route.equals("edit"))routineDraft=alarm.challenges();route=next;render();}
    private void render(){if(toneScreen!=null&&!route.equals("sound"))toneScreen.stop();LinearLayout body=Design.page(this,false,null,null);
        switch(route){case "smart":smart(body);break;case "sound":sound(body);break;case "soundmodes":AlarmSoundModesUi.render(this,body,alarm,this::render,()->go("sound"),this::openDialog);break;case "gentle":gentle(body);break;case "snooze":snooze(body);break;case "challenge":challenges(body);break;case "task":task(body);break;default:editor(body);}
        if(restoredPicker!=null){Bundle saved=restoredPicker;restoredPicker=null;if("time".equals(saved.getString("sleepPickerKind")))openDialog(()->SleepPicker.time(this,"Alarm time",alarm.hour*60+alarm.minute,value->{alarm.hour=value/60;alarm.minute=value%60;render();}));else {android.view.View row=findSetting(body,saved.getString("sleepPickerTitle"));if(row!=null)row.performClick();}if(settingsDialog instanceof SleepPicker.StateDialog)settingsDialog.onRestoreInstanceState(saved);}
    }
    private android.view.View findSetting(android.view.View view,String title){if(title!=null&&android.text.TextUtils.equals(title,view.getContentDescription()))return view;if(view instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++){android.view.View found=findSetting(group.getChildAt(n),title);if(found!=null)return found;}return null;}
