        Design.text(body,"Wake window",16,600,Design.INK);Design.space(body,8);Design.text(body,alarm.smartWindow==0?"Off":(alarm.solar==null?Design.clock(this,alarm.hour*60+alarm.minute-alarm.smartWindow):RecordUi.clock(this,Math.max(0,AlarmSkips.next(this,alarm)-alarm.smartWindow*60000L),java.time.ZoneId.systemDefault()))+" – "+displayTime(this,alarm),27,700,Design.INK);Design.space(body,24);
        picker(body,"clock","Window length",null,alarm.smartWindow==0?"Off":alarm.smartWindow+" min",alarm.smartWindow,new int[]{0,5,10,15,20,30,45,60},n->n==0?"Off":n+" min",n->alarm.smartWindow=n);Design.line(body);
