            picker(body,"clock","Backup sound duration",null,alarm.timing.backupSeconds==0?"Continuous":alarm.timing.backupSeconds+" sec",alarm.timing.backupSeconds,new int[]{0,30,60,120,180,300},n->n==0?"Continuous":n+" sec",n->{alarm.timing=alarm.timing.duration(n);alarm.timingInvalid=false;});Design.line(body);
