    private static int[] snoozeDurations(){return java.util.stream.IntStream.concat(java.util.stream.IntStream.rangeClosed(1,15),java.util.stream.IntStream.of(20,30,45,60)).toArray();}
    private static String inputLabel(AlarmInputs.Keys keys){return switch(keys){case SNOOZE->"Snooze";case IGNORE->"No action";default->"Phone volume";};}
    private void range(LinearLayout p,String title,int value,int min,int max,java.util.function.IntConsumer change){TextView label=Design.text(p,title+" · "+value,15,500,Design.INK);SeekBar seek=new SeekBar(this);seek.setContentDescription(title);AlarmSliders.style(seek);seek.setMax(max-min);seek.setProgress(value-min);seek.setMinimumHeight(Design.dp(this,48));p.addView(seek,new LinearLayout.LayoutParams(-1,Design.dp(this,56)));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){label.setText(title+" · "+(n+min));if(user)change.accept(n+min);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});}
    private void save(){if(alarm.snoozeTotalInvalid){saveError="Review the total snooze time in Snooze before saving.";render();return;}if(alarm.solarInvalid){saveError="Review sunrise time settings or choose Clock time.";render();return;}if(alarm.soundModeInvalid){saveError="Review sound playback mode before saving.";render();return;}if(alarm.timingInvalid){saveError="Review backup and timeout settings in Snooze before saving.";render();return;}if(alarm.inputsInvalid){saveError="Review flip and volume-key settings in Snooze before saving.";render();return;}if(alarm.dateInvalid){saveError="Choose a valid alarm date or clear it.";render();return;}if(alarm.enabled&&alarm.date!=null&&alarm.next(System.currentTimeMillis())<=0){saveError="That alarm date has passed. Choose a future date.";render();return;}if(alarm.enabled&&!AlarmScheduling.port.allowed(this)){new AlertDialog.Builder(this).setTitle("Allow exact alarms").setMessage("Android requires Alarms & reminders access to schedule this alarm. Your draft is preserved.").setPositiveButton("Open settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())))).setNegativeButton("Keep editing",null).show();return;}
        if(alarm.challenges().tasks.stream().anyMatch(task->task.type.equals("NFC"))&&Prefs.text(this,"nfcTag","").isEmpty()){Ui.toast(this,"Enroll an NFC tag in Alarms → Alarm options before using this challenge.");return;}
        if(alarm.routineInvalid){Ui.toast(this,"Choose and save a valid challenge routine first.");return;}
        // Persist the guarded draft first; an unconfirmed scheduling marker survives interruption.
        try{alarm=AlarmSkips.edit(this,store,alarm,originalAlarm,originalExisted);originalAlarm=Alarm.read(alarm.json());originalExisted=true;WakeChecks.alarmEdited(this,store,alarm);if(!alarm.scheduleError.isEmpty()){saveError=alarm.scheduleError;render();return;}saveError="";finish();}catch(AlarmSkips.Changed changed){saveError=changed.getMessage();render();}catch(RuntimeException e){saveError="Alarm could not be saved or scheduled. Check alarm access and try again.";render();}
    }
    static String displayTime(android.content.Context c,Alarm a){if(a.solarInvalid)return "Review sunrise";if(a.solar!=null){long at=AlarmSkips.next(c,a);if(at>0)return RecordUi.clock(c,at,java.time.ZoneId.systemDefault());return "Sunrise";}return Design.clock(c,a.hour*60+a.minute);}
    static String toneName(String tone){return AlarmTones.name(tone);}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==PictureMatchActivity.ENROLL){pictureResult(result,data);return;}if(r==GoalAlarmTimeActivity.REQUEST){String expected=goalRequest;goalRequest="";if(result==RESULT_OK&&data!=null&&!expected.isEmpty()&&expected.equals(data.getStringExtra("request"))){try{int value=data.getIntExtra("minute",-1);GoalAlarmPlan.Snapshot plan=GoalAlarmPlan.load(this);if(value<0||value>=1440||value!=plan.time().minute||!plan.identity().equals(data.getStringExtra("plan"))||!java.time.ZoneId.systemDefault().getId().equals(data.getStringExtra("zone")))throw new IllegalArgumentException("Saved plan changed. Open Use sleep plan again.");alarm.hour=value/60;alarm.minute=value%60;goalNotice=alarm.solar==null?"Fixed time copied. Save alarm to keep it.":"Sunrise fallback copied. Save alarm to keep it.";saveError="";}catch(IllegalArgumentException invalid){saveError=invalid.getMessage();}render();}return;}if(r==SunriseTimeActivity.REQUEST){if(result==RESULT_OK&&data!=null&&!solarRequest.isEmpty()&&solarRequest.equals(data.getStringExtra("request"))){solarRequest="";try{int hour=data.getIntExtra("hour",-1),minute=data.getIntExtra("minute",-1);if(hour<0||hour>23||minute<0||minute>59)throw new JSONException("Invalid fallback time");SunriseSchedule value=data.getBooleanExtra("clock",false)?null:SunriseScheduleJson.decode(new JSONObject(data.getStringExtra("solar")));alarm.solar=value;alarm.solarInvalid=false;alarm.hour=hour;alarm.minute=minute;saveError="";}catch(Exception invalid){saveError="Sunrise settings could not be read. Open Time basis to review them.";}render();}else solarRequest="";return;}if(r==343){qrResult(result,data);return;}if(r==AlarmToneImport.REQUEST||r==1){if(toneScreen!=null)toneScreen.result(result,data);return;}}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(toneScreen!=null)toneScreen.focus(focused);if(focused)RecordUi.lightBars(this);}
